describe('Table Loading State', () => {
    beforeEach(() => {
        cy.visit('/table-list'); // Adjust the URL as necessary
    });

    it('should display loading state while data is fetching', () => {
        cy.intercept('GET', '/api/data', { delay: 2000 }).as('fetchData'); // Simulate data fetching
        cy.get('.load-button').click(); // Trigger data fetch
        cy.get('.loading-spinner').should('be.visible'); // Check if loading spinner is visible
        cy.wait('@fetchData'); // Wait for the data to be fetched
        cy.get('.loading-spinner').should('not.exist'); // Check if loading spinner is gone
        cy.get('.data-table').should('be.visible'); // Verify that the data table is visible
    });

    it('should handle error state if data fetching fails', () => {
        cy.intercept('GET', '/api/data', { statusCode: 500 }).as('fetchDataError'); // Simulate a fetch error
        cy.get('.load-button').click(); // Trigger data fetch
        cy.wait('@fetchDataError'); // Wait for the error response
        cy.get('.error-message').should('be.visible').and('contain', 'Failed to load data'); // Check for error message
        cy.get('.data-table').should('not.exist'); // Verify that the data table is not visible
    });
});
